 private:
  Status BrcInlineGenerate(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis,
                           const std::vector<std::reference_wrapper<const Tensor>> &inputs,
                           const std::vector<std::reference_wrapper<const Tensor>> &outputs, std::string &result) const;

  static std::string GetAscendApiName(const std::string &api_name);

 private:
  bool generalized_brc_inline_scene = false;
  std::vector<uint8_t> input_idx_2_brc_inline;
};
}  // namespace codegen
