28	
29	Status BinaryApiCall::Generate(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis,
30	                               const std::vector<std::reference_wrapper<const Tensor>> &inputs,
31	                               const std::vector<std::reference_wrapper<const Tensor>> &outputs,
32	                               std::string &result) const {
33	  if (generalized_brc_inline_scene) {
34	    return BrcInlineGenerate(tpipe, current_axis, inputs, outputs, result);
35	  }
36	  size_t x1_idx = 0;
37	  size_t x2_idx = 1;
38	  bool switch_scalar = false;
39	  // 对于input[0]为Data节点，input[1]为Scalar节点，scheduler无法调换顺序，需要codegen调换顺序
40	  // input[0] input[1] 都为Scalar输入的情况不进行调换
41	  if (inputs[0].get().IsAnyScalar() && !(inputs[1].get().IsAnyScalar())) {
42	    x1_idx = 1;
43	    x2_idx = 0;
44	    switch_scalar = true;
45	  }
46	  const auto &x1 = inputs[x1_idx].get();
47	  const auto &x2 = inputs[x2_idx].get();
48	
49	  GELOGD("x2, is_constant:%d, is_ub_scalar:%d, need_gen_get_value_of_ub_scalar:%d",
50	         static_cast<int32_t>(x2.is_constant), static_cast<int32_t>(x2.is_ub_scalar),
51	         static_cast<int32_t>(x2.need_gen_get_value_of_ub_scalar));
52	
53	  const auto &y = outputs[0].get();
54	
55	  (void)RegisterBasicDumpParam(this->api_name_, inputs, outputs, CombinedExprFactory::SymbolVar(x1.actual_size.Str()));
56	
57	  stringstream ss;
58	  std::string dtype_name;
59	  GE_CHK_STATUS_RET(Tensor::DtypeName(x1.dtype, dtype_name), "Codegen get data type:%d failed",
60	                    static_cast<int32_t>(x1.dtype));
61	  const std::string is_scalar_latter = switch_scalar ? "false" : "true";
62	  // 获取tmp_buf复用TBuf的id
63	  int64_t life_time_axis_id = -1L;
64	  int64_t id = -1L;
65	  auto it = this->tmp_buf_id.find(life_time_axis_id);
66	  if (it != this->tmp_buf_id.end()) {
67	    id = it->second;
68	  }
69	
70	  if (x1.IsAnyScalar() && x2.IsAnyScalar()) {  // 两个输入都是Scalar
71	    ss << this->api_name_ << "s(";
72	    ss << y << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, y) << "], ";
73	    ss << "(" << dtype_name << ")" << x1.GetScalarValue() << ", ";
74	    ss << "(" << dtype_name << ")" << x2.GetScalarValue();
75	    ss << ");" << std::endl;
76	  } else if (x1.IsAnyScalar() || x2.IsAnyScalar()) {  // 只有1个输入是Scalar
77	    if (this->api_name_ == "Div" || this->api_name_ == "Sub") {
78	      GE_ASSERT_TRUE(id != -1L, "BinaryApiCall cannot find tmp buffer id to use.");
79	      ss << this->api_name_ << "s<" << dtype_name << ", " << is_scalar_latter << ">" << "(" << y << "["
80	         << tpipe.tiler.TensorVectorizedOffset(current_axis, y) << "], " << x1 << "["
81	         << tpipe.tiler.TensorVectorizedOffset(current_axis, x1) << "], "
82	         << "(" << dtype_name << ")" << x2.GetScalarValue() << ", " << tpipe.tmp_buf << "_" << std::to_string(id)
83	         << ", " << x1.actual_size << ");" << std::endl;
84	    } else if (this->api_name_ == "DivExtend" || this->api_name_ == "SubExtend") {
85	      ss << this->api_name_ << "s<" << dtype_name << ", " << is_scalar_latter << ">" << "(" << y << "["
86	         << tpipe.tiler.TensorVectorizedOffset(current_axis, y) << "], " << x1 << "["
87	         << tpipe.tiler.TensorVectorizedOffset(current_axis, x1) << "], "
88	         << "(" << dtype_name << ")" << x2.GetScalarValue() << ", " << x1.actual_size << ");" << std::endl;
89	    } else {
90	      ss << this->api_name_ << "s(";
91	      ss << y << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, y) << "], ";
92	      ss << x1 << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, x1) << "], ";
93	      ss << "(" << dtype_name << ")" << x2.GetScalarValue() << ", ";
94	      ss << x1.actual_size;
95	      ss << ");" << std::endl;
96	    }
97	  } else {  // 两个输入都不是Scalar
98	    ss << this->api_name_ << "(" << y << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, y) << "], " << x1
99	       << "[" << tpipe.tiler.TensorVectorizedOffset(current_axis, x1) << "], " << x2 << "["
100	       << tpipe.tiler.TensorVectorizedOffset(current_axis, x2) << "], " << x1.actual_size << ");" << std::endl;
101	  }
102	  result = ss.str();
103	  return af::SUCCESS;
104	}
