111	Status BinaryApiCall::BrcInlineGenerate(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis,
112	                                        const std::vector<std::reference_wrapper<const Tensor>> &inputs,
113	                                        const std::vector<std::reference_wrapper<const Tensor>> &outputs,
114	                                        std::string &result) const {
115	  const auto &x1 = inputs[0].get();
116	  const auto &x2 = inputs[1].get();
117	
118	  const auto &y = outputs[0].get();
119	
120	  std::vector<af::Expression> i0_v_repeates;
121	  std::vector<af::Expression> i1_v_repeates;
122	
123	  for (size_t i = 0UL; i < x1.vectorized_axis.size(); ++i) {
124	    auto pos1 = x1.vectorized_axis_pos[i];
125	    auto pos2 = x2.vectorized_axis_pos[i];
126	    i0_v_repeates.push_back(x1.axis_size[pos1]);
127	    i1_v_repeates.push_back(x2.axis_size[pos2]);
128	  }
129	
130	  GELOGD("input0_v_stride: %s, input1_v_stride: %s", VectorToStr(x1.vectorized_strides).c_str(),
131	         VectorToStr(x2.vectorized_strides).c_str());
132	
133	  std::vector<af::Expression> i0_meger_repeates;
134	  std::vector<af::Expression> i1_meger_repeates;
135	
136	  if (input_idx_2_brc_inline[0] != 0) {
137	    MergeBrcAxisRepeats(i0_v_repeates, i1_v_repeates, x2.vectorized_strides, i0_meger_repeates, i1_meger_repeates);
138	  } else {
139	    MergeBrcAxisRepeats(i1_v_repeates, i0_v_repeates, x1.vectorized_strides, i1_meger_repeates, i0_meger_repeates);
140	  }
141	
142	  auto &meger_shape = (input_idx_2_brc_inline[0] != 0) ? i1_meger_repeates : i0_meger_repeates;
143	
144	  std::string shape =
145	      "{" + tpipe.tiler.ActualSize(meger_shape[0]) + ", " + af::SymbolicUtils::ToString(meger_shape[1]) + "}";
146	
147	  af::Expression v_strides = af::sym::kSymbolZero;
148	  auto &x_in = (input_idx_2_brc_inline[0] != 0) ? x1 : x2;
149	  for (size_t i = 0UL; i < x_in.vectorized_axis_pos.size(); ++i) {
150	    const uint32_t axis_ids = x_in.vectorized_axis_pos[i];
151	    af::Expression cur_axis_strides = y.vectorized_strides[i];
152	    af::Expression cur_axis_repeats = x_in.axis_size[axis_ids];
153	    if (af::SymbolicUtils::StaticCheckEq(cur_axis_repeats, af::sym::kSymbolOne) != af::TriBool::kTrue) {
154	      break;
155	    }
156	    v_strides = ((af::SymbolicUtils::StaticCheckEq(cur_axis_strides, af::sym::kSymbolZero) != af::TriBool::kTrue)
157	                     ? cur_axis_strides
158	                     : v_strides);
159	  }
160	
161	  int64_t type_size = GetSizeByDataType(y.dtype);
162	  stringstream ss;
163	  std::string dtype_name;
164	  GE_CHK_STATUS_RET(Tensor::DtypeName(x1.dtype, dtype_name), "Codegen get data type:%d failed",
165	                    static_cast<int32_t>(x1.dtype));
166	
167	  ss << "BinaryBrcInlineApiWithTwoVectorizedAxis<" << dtype_name << ">" << "(" << y << "["
168	     << tpipe.tiler.TensorVectorizedOffset(current_axis, y) << "], " << x1 << "["
169	     << tpipe.tiler.TensorVectorizedOffset(current_axis, x1) << "], " << x2 << "["
170	     << tpipe.tiler.TensorVectorizedOffset(current_axis, x2) << "], " << tpipe.tiler.ActualSize(meger_shape[0]) << ", "
171	     << tpipe.tiler.ActualSize(meger_shape[1]) << ", " << static_cast<int>(input_idx_2_brc_inline[0] == 0) << ", "
172	     << static_cast<int>(input_idx_2_brc_inline[1] == 0) << ", " << tpipe.tiler.ActualSize(v_strides) << ", "
173	     << static_cast<int>(type_size) << ", &" << GetAscendApiName(this->api_name_) << ", &"
174	     << GetAscendApiName(this->api_name_) << ");" << std::endl;
175	  result = ss.str();
176	  return af::SUCCESS;
177	}
178	
179	Status BinaryApiCall::Init(const ascir::NodeView &node) {
180	  GE_CHK_STATUS_RET(ApiCall::Init(node));
181	  generalized_brc_inline_scene = IsGeneralizeBrcInlineScene(node, input_idx_2_brc_inline);
182	  return af::SUCCESS;
183	}
184	
185	static ApiCallRegister<BinaryApiCall> register_binary_api_call("BinaryApiCall");
186	}  // namespace codegen
